const body = $json.body || $json || {};
const clientId = String(body.client_id || '').trim();
const esUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(clientId);

return [{
  json: {
    // Sin uuid válido no seguimos: Supabase respondería con un error feo de
    // "invalid input syntax for type uuid".
    client_id: esUuid ? clientId : '',
    // Tope de fichas por pasada. Sirve para probar con 10 productos en vez de
    // recorrer el catálogo entero mientras se ajusta algo.
    limite: Number(body.limite) > 0 ? Number(body.limite) : 0,
  },
}];

const pet = $('Leer petición').first().json;
const fila = $input.first().json;
const config = (fila && fila.config) || {};

return [{
  json: {
    ...pet,
    sitemap_url: String(config.catalog_sitemap_url || '').trim(),
    // Opcional: si la tienda tiene miles de URLs y solo unas cuantas son
    // fichas, este patrón evita descargarlas todas para descartarlas después.
    patron_url: String(config.catalog_url_pattern || '').trim(),
    listo: Boolean(fila && fila.client_id && config.catalog_sitemap_url),
  },
}];

